// A package that names no Solid package and imports none: the build does not read it as source (ADR 0981). It runs what it is given in
// the effect the caller hands it (here `createTrackedEffect`).
export function track(effect, read) {
  effect(() => {
    const value = read();
    if (typeof value === "function") value();
  });
}
export function makeReader(effect) {
  return (props) => {
    effect(() => {
      void props.children;
    });
    return null;
  };
}
